// Rakit payload POST /api/v1/prakiraan-beban/ dari baris spreadsheet.
//
// Dipakai oleh dua workflow sekaligus:
//   - node Google Sheets  -> nilai sel datang sebagai STRING
//   - node Extract From File (.xlsx) -> sel Jam/Tanggal bisa jadi ANGKA
//     (serial Excel) atau objek Date, karena di Excel keduanya numerik
// Karena itu semua bentuk di bawah diterima.
//
// Header sheet yang diharapkan: Tanggal | Jam | MW  (tak peduli besar-kecil huruf).
// - Jam boleh "HH:MM", "HH:MM:SS", angka pecahan hari (0.5 = 12:00), atau Date.
// - Boleh juga kolom "Menit" (0..1439) sebagai ganti Jam.
// - MW boleh pakai koma desimal; sel kosong dilewati.
// - Hanya baris H dan H+1 yang dikirim — kurva hari lampau TIDAK ditimpa,
//   karena histori itulah yang dipakai menghitung akurasi di FASOP.

const ZONA = 'Asia/Makassar';
const hariIni = DateTime.now().setZone(ZONA).toISODate();
const besok = DateTime.now().setZone(ZONA).plus({ days: 1 }).toISODate();
const DIIZINKAN = new Set([hariIni, besok]);

// Excel menghitung tanggal sebagai jumlah hari sejak 1899-12-30.
const EPOCH_EXCEL = Date.UTC(1899, 11, 30);

/** Ambil nilai kolom tanpa peduli besar-kecil huruf / spasi. */
function kolom(row, ...nama) {
  const peta = {};
  for (const k of Object.keys(row)) peta[k.trim().toLowerCase()] = row[k];
  for (const n of nama) {
    const v = peta[n.toLowerCase()];
    if (v !== undefined && v !== null && String(v).trim() !== '') return v;
  }
  return null;
}

/** Angka dari sel, toleran koma desimal. NaN kalau bukan angka. */
function angka(v) {
  if (typeof v === 'number') return v;
  return Number(String(v).trim().replace(',', '.'));
}

/**
 * Tanggal sel -> 'YYYY-MM-DD'. Menerima ISO, DD/MM/YYYY, Date, dan serial Excel.
 * Date dari SheetJS dibuat pada tengah malam UTC; Asia/Makassar (+8) masih
 * jatuh di tanggal yang sama, jadi konversi zona di bawah aman.
 */
function normalTanggal(v) {
  if (v == null || String(v).trim() === '') return null;
  if (v instanceof Date) return DateTime.fromJSDate(v).setZone(ZONA).toISODate();

  const n = angka(v);
  if (Number.isFinite(n) && n > 20000) {          // serial Excel (>= th. 1954)
    return new Date(EPOCH_EXCEL + Math.floor(n) * 86400000).toISOString().slice(0, 10);
  }

  const s = String(v).trim();
  for (const fmt of ['yyyy-MM-dd', 'dd/MM/yyyy', 'd/M/yyyy', 'dd-MM-yyyy']) {
    const d = DateTime.fromFormat(s, fmt, { zone: ZONA });
    if (d.isValid) return d.toISODate();
  }
  const iso = DateTime.fromISO(s, { zone: ZONA });
  return iso.isValid ? iso.toISODate() : null;
}

/**
 * Jam sel -> menit sejak 00:00 (0..1439), atau null kalau tak terbaca.
 * Sel waktu di Excel adalah pecahan hari: 0.5 = 12:00, 0.770833 = 18:30.
 */
function normalMenit(jam, menit) {
  if (menit != null) {
    const n = angka(menit);
    return Number.isFinite(n) && n >= 0 && n <= 1439 ? Math.round(n) : null;
  }
  if (jam == null) return null;

  if (jam instanceof Date) {
    // Sel waktu-saja dari SheetJS mendarat di tahun 1899/1900 dengan jam
    // tersimpan sebagai UTC — pakai getter UTC supaya tidak tergeser zona.
    // Sel bertanggal penuh dibaca sebagai waktu lokal seperti biasa.
    return jam.getUTCFullYear() < 1901
      ? jam.getUTCHours() * 60 + jam.getUTCMinutes()
      : jam.getHours() * 60 + jam.getMinutes();
  }

  const s = String(jam).trim();
  const cocok = s.match(/^(\d{1,2}):(\d{2})/);
  if (cocok) {
    const hh = Number(cocok[1]), mm = Number(cocok[2]);
    return hh <= 23 && mm <= 59 ? hh * 60 + mm : null;
  }

  const n = angka(s);
  if (Number.isFinite(n) && n >= 0 && n < 2) {     // pecahan hari
    return Math.round((n - Math.floor(n)) * 1440);
  }
  return null;
}

const data = [];
const dilewati = [];
const takTerbaca = [];

for (const item of $input.all()) {
  const row = item.json;

  const mwMentah = kolom(row, 'mw', 'beban', 'beban (mw)', 'prakiraan');
  if (mwMentah == null) continue;                 // sel kosong: wajar, lewati

  const jam = kolom(row, 'jam', 'waktu', 'time');
  const menitKolom = kolom(row, 'menit', 'minute');
  if (jam == null && menitKolom == null) continue; // baris judul / baris kosong

  const menit = normalMenit(jam, menitKolom);
  if (menit == null) {
    takTerbaca.push(String(jam ?? menitKolom));
    continue;
  }

  const tanggal = normalTanggal(kolom(row, 'tanggal', 'date'));
  // Sheet satu hari tanpa kolom Tanggal -> tanggal null, dipakai default
  // server (hari ini). Kalau ada kolom Tanggal, saring ke H dan H+1 saja.
  if (tanggal !== null && !DIIZINKAN.has(tanggal)) {
    dilewati.push(tanggal);
    continue;
  }

  const baris = { menit, mw: mwMentah };
  if (tanggal !== null) baris.tanggal = tanggal;
  data.push(baris);
}

if (data.length === 0) {
  throw new Error('Tidak ada baris prakiraan H/H+1 yang terbaca dari sheet — '
    + 'periksa nama kolom (Tanggal/Jam/MW) dan isi sheet.'
    + (takTerbaca.length ? ' Kolom Jam tidak terbaca, contoh: ' + takTerbaca.slice(0, 3).join(', ') : ''));
}

return [{ json: { sumber: 'roh-sulbagsel', data, _dilewati: dilewati.length, _jam_tak_terbaca: takTerbaca.length } }];
